# Questions and notes
#
# A question has multiple-choice items, a free-text reason, or both. Until it
# is submitted, the reader sees the form. Afterward the answers are fixed: the
# form is replaced by the answers and the feedback, so a prediction cannot be
# changed after the result is shown.
#
# Labels may contain simple HTML (<i>, <sub>, <b>, entities). Notes are kept
# as plain text, so they can be downloaded.

# One multiple-choice item: its input name, its label and the named choices.
item <- function(name, label, choices) list(name = name, label = label, choices = choices)

# Text for the notes, without the markup the page uses.
plain_text <- function(x) {
  if (is.null(x)) return(NULL)
  x <- gsub("<sub>(.*?)</sub>", "_\\1", x, perl = TRUE)
  # Remove the markup used by labels without swallowing mathematical inequalities.
  x <- gsub("</?(?:i|b|sub|sup|br|em|strong)\\s*/?>", "", x, perl = TRUE)
  # Greek letters are spelled out, so the notes read the same in any font.
  x <- gsub("&alpha;", "alpha", x, fixed = TRUE)
  x <- gsub("&beta;", "beta", x, fixed = TRUE)
  x <- gsub("&eta;", "eta", x, fixed = TRUE)
  x <- gsub("&gamma;", "gamma", x, fixed = TRUE)
  x <- gsub("&theta;", "theta", x, fixed = TRUE)
  x <- gsub("&ndash;", "–", x, fixed = TRUE)
  x <- gsub("&minus;", "−", x, fixed = TRUE)
  x <- gsub("&plusmn;", "±", x, fixed = TRUE)
  x <- gsub("&nbsp;", " ", x, fixed = TRUE)
  gsub("\\s+", " ", trimws(x))
}

# Draws the question with this id and keeps the submitted answer in
# answers[[id]]: the choice for each item, named by the item, and "reason", the
# text the reader wrote ("" if none). The fixed answer is followed by
# feedback(a); on_submit(a) runs once, when the answer is saved.
ask_server <- function(id, input, output, answers, items, reason = NULL,
                       button = "Save my answer", feedback = function(a) NULL,
                       on_submit = function(a) NULL, reason_required = FALSE) {
  # The message has its own output, so showing it keeps the choices already
  # made. It is kept with the answers, so starting a part again clears it.
  msg_id <- paste0(id, "_msg")
  output[[msg_id]] <- renderUI(
    if (!is.null(answers[[msg_id]])) p(class = "msg", answers[[msg_id]]))

  output[[id]] <- renderUI({
    a <- answers[[id]]
    if (is.null(a)) {
      tagList(
        lapply(items, function(it) div(class = "item",
          radioButtons(paste0(id, "_", it$name),
                       span(class = "item-label", HTML(it$label)), width = "100%",
                       choiceNames = lapply(unname(it$choices), HTML),
                       choiceValues = names(it$choices), selected = character(0)))),
        if (!is.null(reason))
          div(class = "reasoning",
            textAreaInput(paste0(id, "_reason"), reason, rows = 2, width = "100%")),
        actionButton(paste0(id, "_go"), button, class = "btn-submit"),
        uiOutput(msg_id, role = "status")
      )
    } else {
      tagList(
        div(class = "answered",
          lapply(items, function(it) p(
            if (!is.null(it$label)) span(class = "answered-label", HTML(it$label)),
            span(class = "answered-choice", HTML(it$choices[[a[[it$name]]]])))),
          if (nzchar(a$reason)) p(span(class = "answered-label", "You wrote"),
                                  span(class = "answered-choice", a$reason))),
        div(class = "feedback", feedback(a))
      )
    }
  })

  observeEvent(input[[paste0(id, "_go")]], {
    if (!is.null(answers[[id]])) return()     # already answered, e.g., a double click
    chosen <- lapply(items, function(it) input[[paste0(id, "_", it$name)]])
    if (any(vapply(chosen, function(v) is.null(v) || !nzchar(v), logical(1)))) {
      answers[[msg_id]] <- "Choose an answer to each question first."
      return()
    }
    a <- setNames(chosen, vapply(items, `[[`, "", "name"))
    written <- input[[paste0(id, "_reason")]]
    a$reason <- trimws(if (is.null(written)) "" else written)
    if (reason_required && !nzchar(a$reason)) {
      answers[[msg_id]] <- "Write a sentence about your reasoning before continuing."
      return()
    }
    answers[[msg_id]] <- NULL
    answers[[id]] <- a
    on_submit(a)
  })
}

# Clears the answers to the questions with these ids, and their messages, so
# that each question shows its form again. The notes are kept.
clear_answers <- function(answers, ids) {
  for (id in ids) {
    answers[[id]] <- NULL
    answers[[paste0(id, "_msg")]] <- NULL
  }
}


# Notes
# One entry per saved answer or further result viewed: its step and topic,
# what was asked, what the reader said, the result shown, the settings that
# produced it, and what is still open.

note <- function(step, topic, question, answer, result = NULL, open = NULL,
                 settings = NULL) {
  list(step = step, topic = topic, question = plain_text(question),
       answer = plain_text(answer), result = plain_text(result),
       settings = plain_text(settings), open = plain_text(open),
       time = format(Sys.time(), "%H:%M %Z"))
}

# Newest first; only the newest entry starts open.
notes_ui <- function(entries) {
  if (!length(entries))
    return(p(class = "muted", "Your answers will appear here as you go."))
  entries <- rev(entries)
  tagList(lapply(seq_along(entries), function(i) {
    e <- entries[[i]]
    tags$details(class = "note", open = if (i == 1) NA else NULL,
      tags$summary(
        span(class = "note-step", paste0(e$step, ", ", e$topic)),
        span(class = "note-q", e$question)),
      p(span(class = "note-label", "You: "), e$answer),
      if (!is.null(e$result)) p(span(class = "note-label", "Result: "), e$result),
      if (!is.null(e$settings)) tags$details(class = "note-settings",
                                  tags$summary("Settings"), p(e$settings)),
      if (!is.null(e$open)) p(span(class = "note-label", "Still open: "), e$open))
  }))
}

notes_text <- function(entries) {
  if (!length(entries)) return("No answers recorded.")
  lines <- c("Notes from the companion app to 'Thinking with Models through Simulation",
             "to Guide Scientific Inquiry'", format(Sys.time(), "%Y-%m-%d %H:%M %Z"), "")
  for (e in entries) {
    lines <- c(lines, paste0(e$step, ", ", e$topic, " (", e$time, ")"),
               paste0("  Question:   ", e$question),
               paste0("  You:        ", e$answer),
               if (!is.null(e$result)) paste0("  Result:     ", e$result),
               if (!is.null(e$settings)) paste0("  Settings:   ", e$settings),
               if (!is.null(e$open)) paste0("  Still open: ", e$open), "")
  }
  lines
}

// Moving between the steps of the inquiry, sections that start closed on
// narrow screens, and saving the notes.
document.addEventListener('DOMContentLoaded', function () {
  // The flags that complete Steps 1 to 5, which app.R sends as scene_done.
  var milestones = ['done_q1', 'done_q2', 'done_q3c', 'done_q4b', 'done_e6'];
  var completed = {};
  var currentStep = 1;
  var stepButtons = document.querySelectorAll('[data-step-target]');
  // A step's button is enabled once every earlier step is complete.
  function updateProgress() {
    var available = 1;
    while (available <= milestones.length && completed[milestones[available - 1]]) available++;
    currentStep = Math.min(currentStep, available);
    stepButtons.forEach(function (button) {
      var step = Number(button.dataset.stepTarget);
      button.disabled = step > available;
      button.classList.toggle('is-complete', step < available);
      if (step === currentStep) button.setAttribute('aria-current', 'step');
      else button.removeAttribute('aria-current');
      button.setAttribute('aria-label', 'Step ' + step + ': ' + button.lastElementChild.textContent +
        (step < available ? ', completed' : step > available ? ', available after the previous step' : ''));
    });
  }
  function goToStep(next, attempts) {
    if (!next) return;
    var target = next.tagName === 'DETAILS' ? next : next.querySelector('h2') || next;
    // The completion message can arrive just before Shiny reveals the next panel.
    if (!target.getClientRects().length) {
      if ((attempts || 0) < 20) setTimeout(function () { goToStep(next, (attempts || 0) + 1); }, 50);
      return;
    }
    document.querySelectorAll('.inquiry-scene[data-complete="true"]').forEach(function (scene) {
      if (scene !== next) scene.open = false;
    });
    if (next.tagName === 'DETAILS') next.open = true;
    currentStep = Number(next.id.replace('scene-', ''));
    updateProgress();
    target.setAttribute('tabindex', '-1');
    target.focus({ preventScroll: true });
    target.scrollIntoView({ block: 'start' });
    window.dispatchEvent(new Event('resize'));
  }
  stepButtons.forEach(function (button) {
    button.addEventListener('click', function () {
      goToStep(document.getElementById('scene-' + button.dataset.stepTarget));
    });
  });
  updateProgress();
  Shiny.addCustomMessageHandler('scene_done', function (message) {
    completed[message.name] = message.done;
    updateProgress();
    var scene = document.querySelector('[data-done="' + message.name + '"]');
    if (!scene) return;
    scene.dataset.complete = String(message.done);
    if (!message.done) scene.open = true;
  });
  document.querySelectorAll('.inquiry-scene').forEach(function (scene) {
    scene.querySelector('summary').addEventListener('click', function () {
      // Native details toggle after the click; follow a reader who reopens a step.
      setTimeout(function () {
        if (scene.open) {
          currentStep = Number(scene.id.replace('scene-', ''));
          updateProgress();
        }
      }, 0);
    });
    scene.addEventListener('toggle', function () {
      scene.querySelector('.scene-review').textContent = scene.open ? 'Hide details' : 'Review details';
      // Plots need their visible width after a reader reopens an earlier scene.
      if (scene.open) window.dispatchEvent(new Event('resize'));
    });
  });
  document.querySelectorAll('.scene-continue').forEach(function (button) {
    button.addEventListener('click', function () {
      goToStep(document.getElementById(button.dataset.next));
    });
  });
  var notes = document.getElementById('notes_details');
  if (window.matchMedia('(max-width: 960px)').matches) notes.open = false;
  document.querySelector('.notes-jump').addEventListener('click', function () { notes.open = true; });
  if (window.matchMedia('(max-width: 720px)').matches) {
    document.querySelectorAll('[data-mobile-collapse]').forEach(function (group) { group.open = false; });
  }
  // The notes are fetched and then saved from the page. In the version of the
  // app that runs in the browser (made with shinylive), a download request from
  // the link itself does not reach the app, but a fetch does.
  document.getElementById('notes_download').addEventListener('click', function (event) {
    var link = this;
    if (!link.getAttribute('href')) return;
    event.preventDefault();
    fetch(link.href).then(function (response) {
      var name = /filename="([^"]+)"/.exec(response.headers.get('Content-Disposition') || '');
      return response.blob().then(function (blob) {
        var save = document.createElement('a');
        save.href = URL.createObjectURL(blob);
        save.download = name ? name[1] : 'notes.txt';
        document.body.appendChild(save);
        save.click();
        save.remove();
        setTimeout(function () { URL.revokeObjectURL(save.href); }, 1000);
      });
    });
  });
});

/* Plain, paper-like layout. Ink, gray and the colors of B and D are those of
   the paper's figures. */
:root {
  --ink: #252525;
  --grey: #696969;
  --rule: #D9D9D9;
  --tint: #F4F4F2;
  --B: #B64B41;
  --D: #35658D;
}

body { color: var(--ink); font-size: 17px; line-height: 1.6; }
.container { max-width: 1180px; padding: 0 16px; }

.masthead { padding: 28px 0 10px; border-bottom: 1px solid var(--ink); margin-bottom: 4px; }
.masthead h1 { font-size: 1.9rem; font-weight: 600; margin: 0; }
.masthead p { margin: 2px 0 0; color: var(--grey); font-size: .95rem; }

/* Tabs */
.nav-underline { gap: 22px; border-bottom: 1px solid var(--rule); margin-bottom: 18px;
                 font-family: -apple-system, "Helvetica Neue", Arial, sans-serif; font-size: .9rem; }
.nav-underline .nav-link { color: var(--grey); padding: 12px 0 8px; }
.nav-underline .nav-link.active { color: var(--ink); border-bottom-color: var(--ink); font-weight: 600; }

/* Text */
.part { max-width: 760px; padding-bottom: 40px; }
.part.wide { max-width: none; }
.part.wide > p { max-width: 760px; }
.lead { font-size: 1.05rem; color: var(--ink); }
.muted { color: var(--grey); font-size: .9rem; }
h2.opening { font-size: 1.45rem; font-weight: 600; margin: 10px 0 12px; }
h2.about { font-size: 1.3rem; font-weight: 600; margin: 8px 0 12px; }
h3 { font-size: 1.05rem; font-weight: 600; margin: 24px 0 8px; }
h3.sub { font-size: 1rem; margin-top: 20px; }
.aside { color: var(--grey); font-size: .85rem; margin: 6px 0 18px; }
blockquote { border-left: 2px solid var(--ink); padding-left: 12px; margin: 4px 0 14px; }
td.nowrap, span.nowrap { white-space: nowrap; }
details { margin: 4px 0 12px; }
details summary { cursor: pointer; color: var(--grey); }
summary { line-height: 1.45; }
button:focus-visible, a:focus-visible, summary:focus-visible, .scroll-x:focus-visible {
  outline: 2px solid var(--D); outline-offset: 3px;
}
/* Space above the elements the page scrolls to. */
.inquiry-scene, #scene-6, #notes_box, #x_change_explanation { scroll-margin-top: 20px; }

/* The steps, with the notes beside them */
.layout { display: grid; grid-template-columns: minmax(0, 1fr) 270px; gap: 36px; }
.main { min-width: 0; }

/* Notes */
.notes {
  position: sticky; top: 16px; align-self: start; margin-top: 6px;
  max-height: calc(100vh - 32px); overflow-y: auto;
  border-left: 1px solid var(--rule); padding-left: 20px; font-size: .85rem;
  line-height: 1.45;
}
.notes h2 { font-size: 1rem; font-weight: 600; margin: 0 0 10px; }
.notes > details > summary { color: var(--ink); }
.notes > details > summary h2 { display: inline-block; }
#notes_download { display: inline-block; padding: 0 0 12px; }
.note { border-bottom: 1px solid var(--rule); padding: 8px 0; margin: 0; }
.note[open] { padding-bottom: 12px; }
.note p { margin: 0 0 3px; }
.note > summary { color: var(--ink); padding: 5px 0; }
.note > summary::marker { color: var(--grey); }
.note-step { color: var(--grey); font-size: .78rem; text-transform: uppercase; letter-spacing: .03em; }
.note-q { display: block; margin: 3px 0 5px; line-height: 1.4; }
.note-label { font-weight: 600; }
.note-settings { color: var(--grey); overflow-wrap: anywhere; }
/* A small link to the notes, shown only when they sit below the steps. */
.notes-jump { display: none; }

/* Tables */
.training-design { display: grid; grid-template-columns: minmax(0, 1fr) minmax(180px, .8fr);
  gap: 20px; align-items: start; margin: 18px 0; }
.cue-key-box { padding: 12px 16px; background: var(--tint); font-size: .9rem; }
.cue-key-box h3 { margin: 0 0 8px; font-size: .95rem; }
.cue-key { display: grid; grid-template-columns: 1.2em minmax(0, 1fr); gap: 5px 10px; margin: 0; }
.cue-key dt { margin: 0; font-weight: 600; }
.cue-key dd { margin: 0; line-height: 1.45; }
.worked-example { border-top: 1px solid var(--rule); padding: 12px 0; margin: 20px 0; }
.worked-example > summary { color: var(--ink); }
.worked-example[open] > summary { margin-bottom: 14px; }
table.design, table.values { border-collapse: collapse; margin: 10px 0 18px; font-size: .95rem; }
table.design th, table.design td, table.values th, table.values td {
  padding: 4px 18px 4px 0; text-align: left; vertical-align: top; border-bottom: 1px solid var(--rule); }
table.design thead th, table.values thead th { border-bottom: 1px solid var(--ink); font-weight: 600; }
table.values { width: 100%; font-variant-numeric: tabular-nums; }
table.values td:not(:first-child), table.values th:not(:first-child) { text-align: right; }
.cue-B { color: var(--B); font-weight: 600; }
.cue-D { color: var(--D); font-weight: 600; }
.feedback table.values { margin-top: 4px; }
.table-note { font-size: .85rem; color: var(--grey); margin: 4px 0 0; }
.table-note + p, .table-note + .shiny-html-output > p:first-child { margin-top: 12px; }
/* Step 1's first compound trial, with text in its cells */
table.values.two td:first-child { padding-right: 24px; }
table.values.two td:not(:first-child) { text-align: left; }
/* Step 5's repeated experiments */
table.rates th { font-weight: 600; font-size: .85rem; vertical-align: bottom; }
table.rates td:first-child { white-space: nowrap; padding-right: 24px; }
table.rates tr.mine td { font-weight: 600; }
/* Explore's update table: model names over pairs of B and D columns. */
table.grouped { font-size: .88rem; margin-top: 4px; }
table.grouped thead tr:first-child th { text-align: center; border-bottom: 0; padding: 4px 0 0; }
table.grouped thead tr:first-child th span { display: block; margin: 0 4px 0 10px; padding-bottom: 2px;
                                             border-bottom: 1px solid var(--rule); }
/* Wide tables scroll inside their own box on narrow screens. */
.scroll-x { overflow-x: auto; max-width: 100%; }
.small-screen-note { display: none; }

/* Questions and answers */
.question { background: var(--tint); padding: 16px 20px 10px; margin: 18px 0 22px;
            border-left: 2px solid #DDDDD8; }
.question.inner { background: #fff; border: 1px solid var(--rule); }
.question.small { font-size: .95rem; }
.question.small .controls-inline { gap: 0 24px; }
.item { margin-bottom: 4px; }
.item + .item { margin-top: 18px; padding-top: 16px; border-top: 1px solid var(--rule); }
.item-label { font-weight: 600; margin-bottom: 4px; }
.question .radio label, .question .checkbox label, .explore-controls .radio label {
  font-weight: 400; display: flex; align-items: flex-start; gap: .5em; }
.question .radio input, .question .checkbox input, .explore-controls .radio input {
  flex: none; margin: .35em 0 0; }
.question textarea { font-size: .95rem; line-height: 1.5; border-color: #B8B8B3; border-radius: 2px;
                     resize: vertical; }
.reasoning { margin-top: 16px; }
.reasoning label { font-weight: 400; line-height: 1.45; margin-bottom: 8px; }
.btn-submit { background: var(--ink); color: #fff; border: 0; border-radius: 2px;
              padding: 6px 16px; font-size: .9rem; margin: 4px 0 10px; }
.btn-submit:hover, .btn-submit:focus { background: #000; color: #fff; }
.msg { color: var(--B); font-size: .9rem; }
.answered p { margin: 0 0 6px; }
.answered-label { display: block; font-size: .8rem; color: var(--grey); margin-top: 6px; }
.answered-choice { display: block; }
.answered > p + p { margin-top: 12px; }
.feedback { border-top: 1px solid var(--rule); margin-top: 10px; padding-top: 10px; }
.feedback:empty { display: none; }
.feedback h3:first-child { margin-top: 4px; }
.feedback > p:last-child { margin-bottom: 4px; }
/* Step 2: one block per comparison tried */
.try + .try { border-top: 1px solid var(--ink); margin-top: 16px; padding-top: 14px; }
p.another { margin: 14px 0 6px; }
/* Step 5's conclusions. A selection that differs from the app's judgment is
   marked by a rule, not by B's red. */
.statement { border-bottom: 1px solid var(--rule); padding: 8px 0; }
.statement p { margin: 0 0 4px; }
.statement p.disagree { border-left: 3px solid var(--ink); padding-left: 10px; }

/* The step buttons */
.inquiry-progress { margin: 26px 0 0; font-family: -apple-system, "Helvetica Neue", Arial, sans-serif; }
.inquiry-progress ol { list-style: none; display: grid; grid-template-columns: repeat(6, minmax(0, 1fr));
  padding: 0; margin: 0; gap: 6px; }
.inquiry-progress button { width: 100%; min-height: 60px; padding: 8px 3px; background: #fff;
  border: 0; border-bottom: 2px solid var(--rule); color: var(--ink); font-size: .72rem; line-height: 1.3; }
.progress-n { display: block; margin-bottom: 3px; font-size: .8rem; color: var(--grey); }
.inquiry-progress button[aria-current="step"] { border-bottom-color: var(--ink); background: var(--tint); font-weight: 600; }
.inquiry-progress button.is-complete .progress-n::after { content: " ✓"; }
.inquiry-progress button:disabled { color: #767676; border-bottom-style: dotted; }
.inquiry-progress button:not(:disabled):hover { background: var(--tint); }

/* The steps. Once a step is complete, its heading also shows a summary and a
   link that folds or reopens the step. */
h2.step { font-size: 1.3rem; font-weight: 600; margin: 40px 0 12px; padding-top: 18px;
          border-top: 1px solid var(--rule); }
.step-n { display: inline-block; min-width: 1.6em; color: var(--grey); font-weight: 400; }
.inquiry-scene { margin: 0; }
.inquiry-scene > summary { list-style: none; color: var(--ink); }
.inquiry-scene > summary::-webkit-details-marker { display: none; }
.inquiry-scene > summary:focus-visible { outline: 2px solid var(--D); outline-offset: 4px; }
.scene-summary, .scene-review { display: none; }
.inquiry-scene[data-complete="true"] > summary .scene-summary {
  display: block; margin: 0 0 4px; font-size: .9rem; color: var(--grey);
}
.inquiry-scene[data-complete="true"] > summary .scene-review {
  display: inline-block; font-size: .85rem; text-decoration: underline; margin-bottom: 12px;
}
.scene-content > p, .scene-content > ul { margin-bottom: 14px; }
.scene-content .shiny-input-container { max-width: 100%; }
.scene-content > .table-note { margin-top: -4px; margin-bottom: 18px; }
/* The Continue button; this rule must come after .btn-submit, whose margin it
   replaces. */
.scene-continue { margin: 14px 0; min-height: 44px; }
#scene-5 .scene-content > .shiny-panel-conditional > h3,
#scene-5 .scene-content > .shiny-panel-conditional > .shiny-panel-conditional > h3 {
  border-top: 1px solid var(--rule); padding-top: 20px; margin-top: 30px;
}
.further { border-top: 1px solid var(--rule); padding-top: 10px; margin: 18px 0; }
.fig { margin: 8px 0 14px; width: 100%; }
.controls-inline { display: flex; flex-wrap: wrap; gap: 8px 32px; align-items: center; }
.end { margin: 30px 0 10px; }

/* Equations */
.model-equation { max-width: 100%; overflow-x: auto; padding: 10px 4px; margin: 8px 0; }
.model-equation math {
  font-family: "STIX Two Math", "Cambria Math", math;
  font-size: 1.1em;
}
.model-equation mtd { text-align: left; padding: .15em .5em; }
.formula-details { margin: 14px 0 20px; }
.formula-details > summary { color: var(--ink); }
/* Step 1's two learning rules, side by side */
.model-rules { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 20px; margin: 18px 0; }
.model-rule { min-width: 0; padding: 14px 16px 4px; border: 1px solid var(--rule); }
.model-rule h3.sub { margin-top: 0; line-height: 1.4; }
.model-rule p { font-size: .9rem; margin-bottom: 12px; }
.model-rule .model-equation { padding: 12px 0; }
.model-rule .model-equation math { font-size: 1.02em; }

/* Sliders in plain ink */
.irs--shiny .irs-bar, .irs--shiny .irs-single { background: var(--ink); border-color: var(--ink); }
.irs--shiny .irs-handle { border-color: var(--ink); }

/* Explore: the model change first, the other settings grouped below it */
.explore { display: grid; grid-template-columns: 280px minmax(0, 1fr); gap: 36px; }
.explore-controls { font-size: .9rem; padding-right: 20px; border-right: 1px solid var(--rule); }
.explore-controls h3 { font-size: .95rem; margin-top: 16px; }
.control-primary h3 { margin-top: 0; font-size: 1.05rem; }
.control-group { margin: 0; border-top: 1px solid var(--rule); }
.control-group > summary { color: var(--ink); font-weight: 600; padding: 12px 0; }
.control-group .muted { margin-bottom: 12px; font-size: .85rem; }
.explore-controls .shiny-input-container { width: 100%; }
.explore-controls #x_reset { display: inline-block; padding: 14px 0; }
.explore-output { min-width: 0; }
.model-change-explanation { margin-bottom: 18px; }
.model-change-explanation h3 { margin-top: 0; font-size: 1.16rem; line-height: 1.4; }
.starting-states { margin-bottom: 20px; border-block: 1px solid var(--rule); padding: 10px 0; }
.starting-states > summary { color: var(--ink); }
.starting-states[open] > summary { margin-bottom: 12px; }
.starting-states table { width: 100%; }

@media (min-width: 961px) {
  .explore-controls { position: sticky; top: 16px; align-self: start;
                      max-height: calc(100vh - 32px); overflow-y: auto; }
}

/* Narrower screens: the notes move below the steps at 960 px. */
@media (max-width: 960px) {
  .layout { grid-template-columns: minmax(0, 1fr); gap: 0; }
  .notes { position: static; max-height: none; border-left: 0; border-top: 1px solid var(--ink);
           padding: 12px 0 40px; margin-top: 24px; }
  .notes-jump { display: flex; align-items: center; min-height: 44px; position: fixed; right: 16px; bottom: 16px; z-index: 10;
                background: #fff; color: var(--ink); border: 1px solid var(--ink);
                padding: 3px 12px; font-size: .85rem; text-decoration: none; }
}
@media (max-width: 720px) {
  .training-design { grid-template-columns: minmax(0, 1fr); gap: 8px; }
  .explore { grid-template-columns: minmax(0, 1fr); gap: 24px; }
  .explore-controls { padding-right: 0; border-right: 0; }
  .model-rules { grid-template-columns: minmax(0, 1fr); gap: 12px; }
  .inquiry-progress ol { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .inquiry-progress button { min-height: 52px; }
  .small-screen-note { display: block; }
  .btn-submit { min-height: 44px; }
  .formula-details > summary, .worked-example > summary, .further > summary,
  .starting-states > summary { padding-block: 8px; }
}
@media (max-width: 600px) {
  body { font-size: 16px; }
  .question { padding: 14px 14px 8px; }
  .nav-underline { gap: 4px 16px; }
  table.design th, table.design td, table.values th, table.values td { padding-right: 10px; }
}
/* Below 360 px, tighter tables and smaller equations. */
@media (max-width: 360px) {
  table.design, table.values { font-size: .88rem; }
  table.grouped { font-size: .8rem; }
  table.design th, table.design td, table.values th, table.values td { padding-right: 6px; }
  .model-equation math { font-size: .85em; }
  .model-equation mtd { padding-left: .25em; padding-right: .25em; }
}
